 const string W="Assets/ParkingLotEnvironment/CloudPilot/ParkingTraining20261104/Revision2";
 static Transform holder;static Material paint,metal;static List<ParkedObstacle> obstacles=new List<ParkedObstacle>();static List<PracticeBay>bays=new List<PracticeBay>();static List<string>notes=new List<string>();
 static Bounds BoundsOf(GameObject g){var rr=g.GetComponentsInChildren<Renderer>().Where(r=>r.enabled).ToArray();if(rr.Length==0)throw new Exception("No visible geometry: "+g.name);var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
 static Material Mat(string name,Color color,float smooth=.3f){var m=new Material(Shader.Find("Standard")){name=name,color=color};m.SetFloat("_Glossiness",smooth);AssetDatabase.CreateAsset(m,W+"/"+name+".mat");return m;}
