 static GameObject Box(string name,Vector3 p,Vector3 size,Material mat,bool collider=true){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(holder,false);g.transform.position=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;if(!collider)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());Static(g);return g;}
 static Transform Point(string name,Vector3 p,float yaw){var g=new GameObject(name);g.transform.SetParent(holder,false);g.transform.SetPositionAndRotation(p,Quaternion.Euler(0,yaw,0));return g.transform;}
 static void Line(Vector3 a,Vector3 b,float width=.08f){var d=b-a;var g=Box("ParkingLine",(a+b)*.5f,new Vector3(width,.0015f,d.magnitude),paint,false);g.transform.rotation=Quaternion.LookRotation(d);g.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.Off;}
 static void Label(string text,Vector3 p){var g=new GameObject("BayLabel_"+text);g.transform.SetParent(holder,false);g.transform.position=p;g.transform.rotation=Quaternion.Euler(90,0,0);var t=g.AddComponent<TextMesh>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");g.GetComponent<Renderer>().sharedMaterial=t.font.material;t.text=text;t.fontSize=40;t.characterSize=.09f;t.anchor=TextAnchor.MiddleCenter;t.color=new Color(.87f,.87f,.83f);g.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.Off;}
 static void Bay(string id,ParkingManeuver mode,Vector3 center,float width,float length,string context){float yaw=mode==ParkingManeuver.Parallel?0:90;var rot=Quaternion.Euler(0,yaw,0);Vector3[] p={new Vector3(-width/2,0,-length/2),new Vector3(width/2,0,-length/2),new Vector3(width/2,0,length/2),new Vector3(-width/2,0,length/2)};for(int i=0;i<4;i++)Line(center+rot*p[i]+Vector3.up*.004f,center+rot*p[(i+1)%4]+Vector3.up*.004f);Label(id,center+Vector3.up*.006f);var approach=Point("Approach_"+id,mode==ParkingManeuver.Parallel?new Vector3(4.283187f,0,center.z+4.358288f):new Vector3(.8f,0,center.z+4.8f),0);bays.Add(new PracticeBay{id=id,maneuver=mode,center=center,width=width,length=length,headingDegrees=yaw,surroundingVehicles=context,approach=approach});}
 static GameObject Vehicle(GameObject source,string id,string category,Vector3 center,bool parallel=false,Vector3? desired=null){var wrap=new GameObject(id);wrap.transform.SetParent(holder,false);var g=UnityEngine.Object.Instantiate(source,wrap.transform);g.name=source.name;g.SetActive(true);foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);if(parallel)g.transform.RotateAround(BoundsOf(g).center,Vector3.up,90);var b=BoundsOf(g);if(desired.HasValue){var s=desired.Value;var ratio=new Vector3(s.x/b.size.x,s.y/b.size.y,s.z/b.size.z);Func<Vector3,float> factor=axis=>{var v=g.transform.rotation*axis;return Mathf.Abs(v.x)*ratio.x+Mathf.Abs(v.y)*ratio.y+Mathf.Abs(v.z)*ratio.z;};g.transform.localScale=Vector3.Scale(g.transform.localScale,new Vector3(factor(Vector3.right),factor(Vector3.up),factor(Vector3.forward)));b=BoundsOf(g);}g.transform.position+=new Vector3(center.x-b.center.x,.005f-b.min.y,center.z-b.center.z);b=BoundsOf(g);var box=wrap.AddComponent<BoxCollider>();box.center=b.center;box.size=b.size;foreach(var r in g.GetComponentsInChildren<Renderer>()){r.receiveShadows=true;Static(r.gameObject);}obstacles.Add(new ParkedObstacle{id=id,category=category,model=source.name,center=b.center,size=b.size});return wrap;}
 static void Flatbed(GameObject wrap){var all=wrap.GetComponentsInChildren<Renderer>();var b=BoundsOf(wrap);var glass=all.FirstOrDefault(r=>r.name.ToLower().Contains("transperent"));float front=-1;int cut=0;
  foreach(var f in wrap.GetComponentsInChildren<MeshFilter>()){var src=f.sharedMesh;if(!src||!src.isReadable||src.subMeshCount!=1)continue;var vv=src.vertices;var tri=src.triangles;var keep=new List<int>();for(int i=0;i<tri.Length;i+=3){var a=f.transform.TransformPoint(vv[tri[i]]);var d=f.transform.TransformPoint(vv[tri[i+1]]);var c=f.transform.TransformPoint(vv[tri[i+2]]);var mid=(a+d+c)/3;if((mid.x-b.center.x)*front<.45f&&Mathf.Max(a.y,Mathf.Max(c.y,d.y))>1.03f){cut++;continue;}keep.Add(tri[i]);keep.Add(tri[i+1]);keep.Add(tri[i+2]);}if(keep.Count==tri.Length)continue;if(keep.Count==0){f.GetComponent<Renderer>().enabled=false;continue;}var copy=UnityEngine.Object.Instantiate(src);copy.name="Flatbed_"+src.name;var used=keep.Distinct().ToArray();var map=used.Select((v,i)=>new{v,i}).ToDictionary(x=>x.v,x=>x.i);var nn=src.normals;var uv=src.uv;copy.Clear();copy.vertices=used.Select(v=>vv[v]).ToArray();if(nn.Length==vv.Length)copy.normals=used.Select(v=>nn[v]).ToArray();if(uv.Length==vv.Length)copy.uv=used.Select(v=>uv[v]).ToArray();copy.triangles=keep.Select(v=>map[v]).ToArray();copy.RecalculateBounds();copy.RecalculateTangents();Unwrapping.GenerateSecondaryUVSet(copy);AssetDatabase.CreateAsset(copy,AssetDatabase.GenerateUniqueAssetPath(W+"/"+copy.name+".asset"));f.sharedMesh=copy;}
  var center=new Vector3(b.center.x-front*1.05f,.96f,b.center.z);float len=2.95f,width=1.8f;var deck=Box("CargoDeck",center,new Vector3(len,.13f,width),metal,false);deck.transform.SetParent(wrap.transform,true);for(int side=-1;side<=1;side+=2){var wall=Box("CargoSidewall",center+new Vector3(0,.23f,side*(width/2-.035f)),new Vector3(len,.38f,.06f),metal,false);wall.transform.SetParent(wrap.transform,true);for(int k=0;k<5;k++){var rib=Box("CargoRib",wall.transform.position+new Vector3(-len/2+.15f+k*(len-.3f)/4,0,side*.036f),new Vector3(.04f,.34f,.035f),metal,false);rib.transform.SetParent(wrap.transform,true);}}var tail=Box("CargoTailgate",center-new Vector3(front*len/2,-.23f,0),new Vector3(.06f,.38f,width),metal,false);tail.transform.SetParent(wrap.transform,true);var box=wrap.GetComponent<BoxCollider>();var bounds=BoundsOf(wrap);box.center=bounds.center;box.size=bounds.size;var entry=obstacles.Single(x=>x.id==wrap.name);entry.center=bounds.center;entry.size=bounds.size;notes.Add("Porter-class flatbed variant: generic cab-over, cargo shell triangles removed="+cut+"; not an exact Hyundai Porter asset.");}
 static void GroundExtension(GameObject root){var f=root.transform.Find("Zone_Asphalt/default").GetComponent<MeshFilter>();var src=f.sharedMesh;var v=src.vertices;var uv=src.uv;var wp=v.Select(x=>f.transform.TransformPoint(x)).ToArray();int j=Enumerable.Range(1,v.Length-1).First(i=>Mathf.Abs(wp[i].z-wp[0].z)>1),k=Enumerable.Range(1,v.Length-1).First(i=>Mathf.Abs(wp[i].x-wp[0].x)>1);Vector2 scale=new Vector2((uv[k].x-uv[0].x)/(wp[k].x-wp[0].x),(uv[j].y-uv[0].y)/(wp[j].z-wp[0].z));var points=new[]{new Vector3(-10,-.006f,-20),new Vector3(-10,-.006f,-14),new Vector3(8.5f,-.006f,-14),new Vector3(8.5f,-.006f,-20)};var mesh=new Mesh{name="TrainingAsphaltExtension",vertices=points,triangles=new[]{0,1,2,0,2,3},uv=points.Select(p=>uv[0]+new Vector2((p.x-wp[0].x)*scale.x,(p.z-wp[0].z)*scale.y)).ToArray()};mesh.RecalculateNormals();mesh.RecalculateTangents();Unwrapping.GenerateSecondaryUVSet(mesh);AssetDatabase.CreateAsset(mesh,W+"/TrainingAsphaltExtension.asset");var go=new GameObject("Drivable_AsphaltExtension");go.transform.SetParent(holder,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=f.GetComponent<Renderer>().sharedMaterial;go.AddComponent<MeshCollider>().sharedMesh=mesh;Static(go);}
 public static void Apply(GameObject root,string output){holder=new GameObject("ParkingTraining_Layout").transform;holder.SetParent(root.transform,false);paint=Mat("ParkingPaint",new Color(.83f,.83f,.79f),.08f);metal=Mat("CargoWhiteMetal",new Color(.76f,.79f,.8f),.45f);
  // Clear obsolete parking markings and canopy-sized colliders without editing source meshes or prefabs.
  foreach(string name in new[]{"Zone_ParkingPaint","CanopyPass_ParkingPaint_WorldUp","Integrated_FrontCanopy"}){var t=root.transform.Find(name);if(t)t.gameObject.SetActive(false);}foreach(Transform t in root.transform)if(t.name=="tree-small-real")t.gameObject.SetActive(false);var context=root.transform.Find("DaylightPass_Context");foreach(Transform t in context)if(t.name.StartsWith("Daylight_StreetTree_"))t.gameObject.SetActive(false);
  GroundExtension(root);var sources=root.transform.Find("EXISTING_VEHICLES_UNAPPROVED");var hatch=sources.GetChild(1).gameObject;var sedan=sources.GetChild(3).gameObject;var suv=sources.GetChild(0).gameObject;var ev=sources.GetChild(2).gameObject;var truck=context.Find("Daylight_ProvisionalTruck").gameObject;
  float[] zz={-16.5f,-13.5f,-10.5f,-7.5f,-4.5f,-1.5f,1.5f,4.5f,7.5f,10.5f};var blanks=new[]{2,5,7};int count=0;for(int i=0;i<zz.Length;i++){var c=new Vector3(-5.6f,0,zz[i]);if(blanks.Contains(i)){Bay("T"+(Array.IndexOf(blanks,i)+1),ParkingManeuver.ReversePerpendicular,c,i==5?2.6f:2.8f,5.4f,i==5?"승용차와 SUV 사이":"소형차·승용차·카고트럭 주변");}else{var src=i==0||i==6?hatch:i==1||i==8?suv:i==4?truck:sedan;var g=Vehicle(src,"Parked_T_"+i,i==4?"Porter-class cargo":src==hatch?"Compact hatchback":src==suv?"SUV":"Sedan",c,false,i==4?(Vector3?)new Vector3(5.15f,2.75f,1.85f):null);if(i==4)Flatbed(g);count++;}if(!blanks.Contains(i)){Line(new Vector3(-8.3f,.004f,zz[i]-1.4f),new Vector3(-2.9f,.004f,zz[i]-1.4f));Line(new Vector3(-8.3f,.004f,zz[i]+1.4f),new Vector3(-2.9f,.004f,zz[i]+1.4f));Line(new Vector3(-8.3f,.004f,zz[i]-1.4f),new Vector3(-8.3f,.004f,zz[i]+1.4f));}}
  Vehicle(hatch,"Parked_P_Front","Compact hatchback",new Vector3(6.7f,0,-16.3f),true);Vehicle(truck,"Parked_P_BoxTruck","Delivery box truck",new Vector3(6.7f,0,-3),true,new Vector3(1.95f,2.65f,5.15f));Vehicle(suv,"Parked_P_Rear","SUV",new Vector3(6.7f,0,10.3f),true);
  Bay("P1",ParkingManeuver.Parallel,new Vector3(6.7f,0,-9.8f),2.6f,8,"소형차와 탑차 사이");Bay("P2",ParkingManeuver.Parallel,new Vector3(6.7f,0,3.8f),2.6f,8,"탑차와 SUV 사이");sources.gameObject.SetActive(false);
  var layout=holder.gameObject.AddComponent<ParkingTrainingLayout>();layout.bays=bays.ToArray();layout.obstacles=obstacles.ToArray();layout.entrySpawn=Point("Practice_Entry_Spawn",new Vector3(.7f,0,-18.7f),0);var cam=root.GetComponentInChildren<Camera>();cam.transform.SetPositionAndRotation(new Vector3(.6f,1.65f,-19),Quaternion.Euler(0,0,0));
  // Guard rails end at the open entrance; no invisible barrier across the driving aisle.
  var curbMat=root.transform.Find("Zone_Curb/default").GetComponent<Renderer>().sharedMaterial;Box("LeftBoundaryCurbExtension",new Vector3(-8.8f,.07f,-17),new Vector3(.2f,.15f,6),curbMat);Box("RightBoundaryCurbExtension",new Vector3(8.8f,.07f,-17),new Vector3(.2f,.15f,6),curbMat);
  foreach(string zone in new[]{"T","P"}){var pos=new Vector3(zone=="T"?-9:9,2.2f,-11);var baseMat=Mat("SignPanel_"+zone,new Color(.12f,.18f,.24f));Box("TrainingSignFrame_"+zone,pos,new Vector3(1.65f,.74f,.07f),baseMat,false);Box("TrainingSignPost_"+zone,pos-Vector3.up*1.1f,new Vector3(.065f,2.2f,.065f),metal);var panel=GameObject.CreatePrimitive(PrimitiveType.Quad);panel.name="TrainingSignFace_"+zone;panel.transform.SetParent(holder,false);panel.transform.position=pos+new Vector3(0,0,-.042f);panel.transform.localScale=new Vector3(1.6f,.7f,1);UnityEngine.Object.DestroyImmediate(panel.GetComponent<Collider>());var mat=Mat("TrainingSignTexture_"+zone,Color.white,.1f);mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(W+"/Sign"+zone+".png");panel.GetComponent<Renderer>().sharedMaterial=mat;Static(panel);}
  Physics.SyncTransforms();File.WriteAllText(output+"/layout.json",JsonUtility.ToJson(layout,true));notes.Add("3 reverse perpendicular targets, 2 parallel targets; 10 parked practice obstacles; 8.15m maneuvering aisle; open front entry; no app/input changes.");File.WriteAllLines(output+"/build-notes.txt",notes);
 }
